import { lstat, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

/** Directory DevKit keeps per-project state in: caches, builds, sessions, diagnostics. */
export const PROJECT_STATE_DIRECTORY = '.forgeax';

/** Ignores everything beside it, itself included, so the state directory never shows in git. */
export const PROJECT_STATE_GITIGNORE =
  '# Generated by ForgeAX DevKit: local caches and run state.\n*\n';

/**
 * Writes `.forgeax/.gitignore` when DevKit's state directory exists without one, so the
 * directory stays out of version control even in a project whose own `.gitignore` does
 * not list it. Never creates the directory, never replaces an existing file, and never
 * fails the command it follows. Resolves whether a file was written.
 */
export async function ignoreProjectState(root: string | undefined): Promise<boolean> {
  if (root === undefined) return false;
  const directory = resolve(root, PROJECT_STATE_DIRECTORY);
  try {
    if (!(await lstat(directory)).isDirectory()) return false;
    await writeFile(resolve(directory, '.gitignore'), PROJECT_STATE_GITIGNORE, { flag: 'wx' });
    return true;
  } catch {
    return false;
  }
}
